static IEnumerable<Run> InnerRuns(Paragraph para)
{
    foreach (var child in para.ChildElements)
    {
        if (child is Run r) yield return r;
        else if (child is Hyperlink h)
            foreach (var hr in h.Elements<Run>()) yield return hr;
        // w:ins / w:del 直接子级也是 Run（外层是 InsertedRun/DeletedRun），
        // 不展开会被当作「无文本 run」从单元文本里漏掉 → 含遗留修订的段落
        // 必退化成整段删 + 整段增，用户看不出到底改了几个字
        else if (child is InsertedRun ir)
            foreach (var r in ir.Elements<Run>()) yield return r;
        else if (child is DeletedRun dr)
            foreach (var r in dr.Elements<Run>()) yield return r;
    }
}

