/// 回滚窗口复原：回滚段结束后把临时重开的 run 置回 Failed（终态）。
/// 兼容运行期内其它路径将 run 进一步改为 Failed / Terminated / Paused
/// （Paused 通常由确认面板触发；终态由熔断/取消触发），统一回滚到 Failed
/// 之外的合适状态：Paused 保留人工交互结果不回卷；Failed/Terminated 已是终态
/// 直接 no-op；Running 才是 reopen 留下的、需要还原的状态。
pub(crate) fn restore_failed_run_after_rollback<R: tauri::Runtime>(
    app: &AppHandle<R>,
    name: &str,
    session_id: Option<&str>,
) {
    let registry = skill_runs(app);
    let mut runs = registry.lock().unwrap_or_else(|e| {
        eprintln!("[mutex_poisoned] bot_skills::state::skill_runs: {e:?}");
        e.into_inner()
    });
    let Some(run) = runs.get_mut(name) else { return; };
    if run.session_id.as_deref() != session_id {
        return;
    }
    // 仅当仍是「我们 reopen 出来的 Running」才强制覆写；其余状态尊重中间过程。
    if run.state == SkillState::Running {
        run.state = SkillState::Failed;
    }
}

