fn ipv6_is_private(v6: std::net::Ipv6Addr) -> bool {
    if let Some(v4) = v6.to_ipv4_mapped() {
        return ipv4_is_private(v4);
    }
    // 6to4 (2002::/16) 嵌入 IPv4：取低 32 位查内网
    if v6.segments()[0] == 0x2002 {
        let v4 = std::net::Ipv4Addr::new(
            (v6.segments()[1] >> 8) as u8,
            v6.segments()[1] as u8,
            (v6.segments()[2] >> 8) as u8,
            v6.segments()[2] as u8,
        );
        return ipv4_is_private(v4);
    }
    // Teredo (2001::/32)：低 32 位 XOR 0xFFFFFFFF 即对端 IPv4
    if v6.segments()[0] == 0x2001 && v6.segments()[1] == 0 {
        let v4 = std::net::Ipv4Addr::from(u32::from_be_bytes([
            (v6.segments()[6] >> 8) as u8, v6.segments()[6] as u8,
            (v6.segments()[7] >> 8) as u8, v6.segments()[7] as u8,
        ]) ^ 0xFFFF_FFFF);
        return ipv4_is_private(v4);
    }
    v6.is_loopback()
        || v6.is_unspecified()
        || v6.is_unique_local()
        || (v6.segments()[0] & 0xffc0) == 0xfe80
}

