fn parse_tool_call(line: &str) -> Option<(String, String)> {
    let line = line.trim();
    if !line.ends_with(')') {
        return None;
    }
    let open = line.find('(')?;
    let name = line[..open].trim();
    if name.is_empty() || !name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
        return None;
    }
    // 找到与 open 配对的 ')'：跟踪嵌套深度，忽略双/单引号内的括号
    let bytes = line.as_bytes();
    let mut depth = 1usize;
    let mut quote: u8 = 0;
    let mut close = line.len();
    for i in (open + 1)..line.len() {
        let b = bytes[i];
        if quote != 0 {
            if b == b'\\' { continue; }
            if b == quote { quote = 0; }
            continue;
        }
        match b {
            b'"' | b'\'' => quote = b,
            b'(' => depth += 1,
            b')' => {
                depth -= 1;
                if depth == 0 { close = i; break; }
            }
            _ => {}
        }
    }
    if depth != 0 || close >= line.len() {
        return None;
    }
    let args = &line[open + 1..close];
    Some((name.to_string(), args.to_string()))
}

