pub fn behavior_deviation(case_total: usize, hit_fractions: &[(String, f64)]) -> f64 {
    if case_total == 0 {
        return 0.0;
    }
    let avg: f64 = if hit_fractions.is_empty() {
        1.0
    } else {
        hit_fractions.iter().map(|(_, f)| *f).sum::<f64>() / hit_fractions.len() as f64
    };
    (1.0 - avg).clamp(0.0, 1.0)
}

