#[derive(Debug, PartialEq, Eq)]
pub enum TransitionError {
    /// `from == to`，状态未变（无副作用）
    NoOp(ChangeStatus),
    /// `from` 已是终态
    FromTerminal { from: ChangeStatus, to: ChangeStatus },
    /// 拓扑非法（matrix 不允许）
    Illegal { from: ChangeStatus, to: ChangeStatus },
}

impl std::fmt::Display for TransitionError { /* .. */ }
impl std::error::Error for TransitionError {}

pub fn transition(from: ChangeStatus, to: ChangeStatus) -> Result<(), TransitionError> {
    if from == to {
        return Err(TransitionError::NoOp(from));
    }
    if from.is_terminal() {
        return Err(TransitionError::FromTerminal { from, to });
    }
    if can_transition(from, to) {
        Ok(())
    } else {
        Err(TransitionError::Illegal { from, to })
    }
}

