    // Rotate outside the global lock so other audit writers don't serialize on it.
    crate::db::rotate_log_if_large(path, 5 * 1024 * 1024);
    let f = match crate::audit::open_log_append(path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("[py_audit] open {path:?} failed: {e:?}");
            return;
        }
    };
    // Narrow the critical section to the actual write.
    {
        let _g = crate::audit::BOT_LOG_LOCK.lock().unwrap_or_else(|e| {
            eprintln!("[mutex_poisoned] py::audit BOT_LOG_LOCK: {e:?}");
            e.into_inner()
        });
        let ts = chrono::Local::now().format("%Y-%m-%d %H:%M:%S");
        let safe = crate::api_handlers::ratelimit::sanitize_log_line(line);
        if let Err(e) = writeln!(f, "[{ts}] {safe}") {
            eprintln!("[py_audit] write to {path:?} failed: {e:?}");
        }
    }
}

