/** 节点是否落在联动指向的一天（当日有排期或当日完成） */
function nodeMatchesDay(node: GraphNode, dayKey: string): boolean {
  const t = node.task;
  if (!t) return false;
  if (t.planStart && t.planStart.slice(0, 10) === dayKey) return true;
  if (!t.completedAt) return false;
  // 用同一套“YYYY-MM-DD”键比较，避开 toDateString() 的时区坑
  const day = dayKey.slice(0, 10);
  return new Date(t.completedAt).toISOString().slice(0, 10) === day;
}

