function heatColor(level: number): string {
  if (level <= 0) return "var(--inset-bg)";
  // 同步取 CSS 变量值并手动算 mix，避免在旧 WebView 上 color-mix 缺失
  // 导致格子塌成透明。
  const brand = getComputedStyle(document.documentElement).getPropertyValue("--brand").trim() || "#3563b0";
  const ratio = level * 25; // 25 / 50 / 75 / 100
  // 将 brand 与 transparent 按比例叠加（surface 一般为白/深，单色叠加足够）
  return `color-mix(in srgb, ${brand} ${ratio}%, transparent)`;
}

